record.field:
syfte: verifiera att Odoo svarar — returnerar uid, användare, databas och bas-URL
när: som hälso-check av den Odoo-instans där medarbetaren körs
när inte: för att anropa andra Odoo-instanser (använd salt_cmd_run); för att ändra något
exempel: {}
output: {"uid": 1, "user": "admin", "db": "ledningssystem", "base_url": "https://..."}
guardrail: ren läsoperation, säker

async def execute(model, domain="[]", limit=50):
    """Sök records i en Odoo-modell."""
    if model not in env:
        return f"ERROR: modellen '{model}' finns inte"
    try:
        dom = json.loads(domain) if isinstance(domain, str) else domain
    except Exception:
        dom = []
    ids = env[model].sudo().search(dom, limit=int(limit))
    return json.dumps(ids, indent=2)

async def execute(model, ids="[]", fields="[]"):
    """Läs fält från records i en Odoo-modell."""
    if model not in env:
        return f"ERROR: modellen '{model}' finns inte"
    try:
        rec_ids = json.loads(ids) if isinstance(ids, str) else ids
        flds = json.loads(fields) if isinstance(fields, str) else fields
    except Exception:
        return "ERROR: ids/fields måste vara giltig JSON"
    recs = env[model].sudo().browse(rec_ids)
    data = recs.read(flds or None)
    return json.dumps(data, indent=2, default=str)

async def execute(model, domain="[]"):
    """Räkna records i en Odoo-modell."""
    if model not in env:
        return f"ERROR: modellen '{model}' finns inte"
    try:
        dom = json.loads(domain) if isinstance(domain, str) else domain
    except Exception:
        dom = []
    return json.dumps({'count': env[model].sudo().search_count(dom)}, indent=2)
